import{_ as e,C as o,o as n,c as s,ai as r,E as i}from"./chunks/framework.BBSijY9B.js";const x=JSON.parse('{"title":"快速开始","description":"从零开始：认识 Grok Bot、创建第一个 Bot、把任务交代清楚。","frontmatter":{"title":"快速开始","description":"从零开始：认识 Grok Bot、创建第一个 Bot、把任务交代清楚。","wordCount":398,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"快速开始 | WANGXXXL"}],["meta",{"property":"og:description","content":"从零开始：认识 Grok Bot、创建第一个 Bot、把任务交代清楚。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/start/"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/start-472255ee5d.png"}],["meta",{"property":"og:image:alt","content":"快速开始 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"快速开始 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"从零开始：认识 Grok Bot、创建第一个 Bot、把任务交代清楚。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/start-472255ee5d.png"}],["meta",{"name":"twitter:image:alt","content":"快速开始 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/start/"}]]},"headers":[],"relativePath":"start/index.md","filePath":"start/index.md","lastUpdated":1792499451000}'),l={name:"start/index.md"};function p(c,t,d,g,m,h){const a=o("SectionHub");return n(),s("div",null,[t[0]||(t[0]=r(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>第一次用 Grok Bot，按下面的顺序花 30 分钟，就能让它替你完成第一件真事。</p><h2 id="_30-分钟上手路线" tabindex="-1">30 分钟上手路线 <a class="header-anchor" href="#_30-分钟上手路线" aria-label="Permalink to &quot;30 分钟上手路线&quot;">​</a></h2><div class="steps"><ol><li><strong>5 分钟 · 搞清它是什么</strong>：读<a href="/start/what-is-grok-bot">什么是 Grok Bot</a>。记住一句话：它不只是回答问题，而是有一台自己的云电脑，能打开网页、处理文件、用你连接的应用把事情做完，你关了电脑它也照常干活。</li><li><strong>10 分钟 · 建第一个 Bot</strong>：跟着<a href="/start/create-first-bot">创建第一个 Bot</a>，给它起个名字、写一句&quot;你负责什么&quot;。<strong>先只建一个</strong>，等事情明显分成几块再拆。</li><li><strong>5 分钟 · 学会交代任务</strong>：读<a href="/start/brief-tasks-clearly">把任务交代清楚</a>，记住五个要素：要什么结果、去哪里找、背景信息、边界、完成标准。</li><li><strong>10 分钟 · 做第一件事</strong>：从<a href="/start/five-things-day-one">第一天可以试的 5 件事</a>里挑一件，现在就发出去。</li></ol></div><h2 id="第一条消息可以这样发" tabindex="-1">第一条消息可以这样发 <a class="header-anchor" href="#第一条消息可以这样发" aria-label="Permalink to &quot;第一条消息可以这样发&quot;">​</a></h2><p>不知道发什么，就复制这段，把方括号换成你自己的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是我的[工作助理]。今天先帮我做一件事：</span></span>
<span class="line"><span>查一下[某个你关心的话题]最近 7 天的公开动态，</span></span>
<span class="line"><span>整理成 5 条以内的要点，每条一句话加原文链接。</span></span>
<span class="line"><span>拿不准的信息标注&quot;待核实&quot;，不要编。做完告诉我你用了哪些来源。</span></span></code></pre></div><p>看它做的过程：打开它的电脑预览，你会看到它真的在开网页、翻资料。这就是它和普通聊天 AI 最大的区别。</p><div class="tip custom-block"><p class="custom-block-title">新手最常见的三个误区</p><ul><li><strong>一上来就建五六个 Bot</strong>：分工还不清楚时，Bot 越多越乱。</li><li><strong>任务只说一句&quot;帮我看看&quot;</strong>：没有来源和输出格式，结果一定很泛。</li><li><strong>还没手动跑顺就设定时</strong>：先当一次性任务做通，再考虑<a href="/automation/routines">例程</a>。</li></ul></div>`,9)),i(a,{section:"start"})])}const _=e(l,[["render",p]]);export{x as __pageData,_ as default};
